project_task.solution:
const TICK_MS = 100; // 1000 (1 second) in the real game
let timeLeft = 10;
let timer = null;
const timeEl = document.querySelector("#time");
const info = document.querySelector("#info");

function tick() {
  // take 1 away (not below 0), write it into #time; at 0 stop and write "Time's up!"
  if (timeLeft > 0) timeLeft--;
  timeEl.textContent = timeLeft;
  if (timeLeft === 0) {
    clearInterval(timer);
    timer = null;
    info.textContent = "Time's up!";
  }
}

function startTimer() {
  // stop the old timer, set the time to 10, start it with setInterval
  clearInterval(timer);
  timeLeft = 10;
  timeEl.textContent = timeLeft;
  info.textContent = "Collect the stars!";
  timer = setInterval(tick, TICK_MS);
}

document.querySelector("#pilot-form").addEventListener("submit", (e) => {
  e.preventDefault();
  startTimer();
});
